  ArchivoBlack_400Regular,
  useFonts as useArchivo,
} from '@expo-google-fonts/archivo-black';
import {
  IBMPlexSans_400Regular,
  IBMPlexSans_600SemiBold,
  useFonts as useIBM,
} from '@expo-google-fonts/ibm-plex-sans';

SplashScreen.preventAutoHideAsync();

