### M2.1 — Supabase project + schema + RLS

**Goal:** All database tables exist with Row-Level Security (RLS — a database feature where each row checks who is allowed to see it before returning results) so members can only ever read and write their own rows.

**Build prompt:**

```
Run this SQL in the Supabase dashboard → SQL Editor. No app code changes in this slice.

--- STEP 1: Private schema for the roles table (not exposed via the auto-generated API) ---
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM anon, authenticated;

CREATE TABLE private.roles (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  role    text NOT NULL CHECK (role IN ('member', 'coach'))
);
GRANT SELECT ON private.roles TO postgres; -- needed for SECURITY DEFINER function below

--- STEP 2: Helper function so RLS policies can check the coach role
--- without granting app users direct access to private.roles ---
CREATE OR REPLACE FUNCTION public.is_coach()
RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path = private AS $$
  SELECT EXISTS (SELECT 1 FROM private.roles WHERE user_id = auth.uid() AND role = 'coach');
$$;

--- STEP 3: Profiles (extends auth.users; holds sensitive body measurements) ---
CREATE TABLE public.profiles (
  id           uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email        text NOT NULL,
  weight_kg    numeric,
  measurements jsonb,
  created_at   timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "member reads own profile"   ON public.profiles FOR SELECT USING (auth.uid() = id);
CREATE POLICY "member updates own profile" ON public.profiles FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "member inserts own profile" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);

--- STEP 4: Plan templates (coach writes; authenticated members read) ---
CREATE TABLE public.plan_templates (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name                text NOT NULL,
  day_of_week         integer NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),
  week_number         integer NOT NULL CHECK (week_number BETWEEN 1 AND 4),
  workout_name        text NOT NULL,
  exercises           jsonb NOT NULL,
  created_at          timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.plan_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "authenticated members read templates"
  ON public.plan_templates FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "coach inserts templates"
  ON public.plan_templates FOR INSERT WITH CHECK (public.is_coach());
CREATE POLICY "coach updates templates"
  ON public.plan_templates FOR UPDATE USING (public.is_coach());

--- STEP 5: Workouts ---
CREATE TABLE public.workouts (
  id        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  member_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  date      date NOT NULL,
  name      text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.workouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "member sees own workouts"    ON public.workouts FOR SELECT USING (auth.uid() = member_id);
CREATE POLICY "member inserts own workouts" ON public.workouts FOR INSERT WITH CHECK (auth.uid() = member_id);
CREATE POLICY "member updates own workouts" ON public.workouts FOR UPDATE USING (auth.uid() = member_id);

--- STEP 6: Sets ---
CREATE TABLE public.sets (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workout_id uuid NOT NULL REFERENCES public.workouts(id) ON DELETE CASCADE,
  member_id  uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  exercise   text NOT NULL,
  reps       integer NOT NULL CHECK (reps > 0),
  weight_kg  numeric NOT NULL CHECK (weight_kg >= 0),
  logged_at  timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.sets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "member sees own sets"    ON public.sets FOR SELECT USING (auth.uid() = member_id);
CREATE POLICY "member inserts own sets" ON public.sets FOR INSERT WITH CHECK (auth.uid() = member_id);

--- STEP 7: Videos ---
CREATE TABLE public.videos (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workout_id   uuid NOT NULL REFERENCES public.workouts(id) ON DELETE CASCADE,
  member_id    uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  storage_path text NOT NULL,
  feedback     text,
  created_at   timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "member sees own videos"    ON public.videos FOR SELECT USING (auth.uid() = member_id);
CREATE POLICY "member inserts own videos" ON public.videos FOR INSERT WITH CHECK (auth.uid() = member_id);
CREATE POLICY "member updates own videos" ON public.videos FOR UPDATE USING (auth.uid() = member_id);

--- STEP 8: Subscriptions (only Edge Functions write via service-role key) ---
CREATE TABLE public.subscriptions (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  member_id  uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status     text NOT NULL CHECK (status IN ('active', 'expired', 'cancelled')),
  product_id text NOT NULL,
