);
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "member reads own subscription" ON public.subscriptions FOR SELECT USING (auth.uid() = member_id);

--- STEP 9: Private storage bucket for videos ---
-- In the Supabase dashboard → Storage → New bucket:
