  // JavaScript's getDay() returns 0=Sun, 1=Mon … 6=Sat.
  // Convert to our schema convention: 1=Mon … 7=Sun.
  const jsDay = new Date().getDay();
  const dayOfWeek = jsDay === 0 ? 7 : jsDay;

