import * as ImagePicker from 'expo-image-picker';
import * as Crypto from 'expo-crypto';
import { supabase } from '../../src/lib/supabase';

async function handleRecordVideo() {
  // 1. Request permission
  const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
  if (status !== 'granted') {
    Alert.alert('Permission needed', 'Please allow access to your video library in Settings.');
    return;
  }

  // 2. Pick video (max 10 seconds)
  const result = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ImagePicker.MediaTypeOptions.Videos,
    videoMaxDuration: 10,
    quality: 0.7,
  });
  if (result.canceled) return;
  const uri = result.assets[0].uri;

  setUploading(true); // show spinner

  // 3. Upload to private "videos" bucket under {userId}/{uuid}.mp4
  const { data: { user } } = await supabase.auth.getUser();
  const videoId = Crypto.randomUUID();
  const path = `${user!.id}/${videoId}.mp4`;

  const response = await fetch(uri);
  const blob = await response.blob();

  const { error: uploadError } = await supabase.storage
    .from('videos')
    .upload(path, blob, { contentType: 'video/mp4', upsert: false });

  if (uploadError) {
    setUploading(false);
    Alert.alert('Upload failed', 'Could not upload your video. Check your connection and try again.');
    return;
  }

  // 4. Insert video row
  const { data: videoRow, error: insertError } = await supabase
    .from('videos')
    .insert({ workout_id: workoutId, member_id: user!.id, storage_path: path })
    .select()
    .single();

  setUploading(false);
  if (insertError) { Alert.alert('Error', insertError.message); return; }

  setUploadedFeedback('Video uploaded! Checking form…');
  // Will call Edge Function in next slice — leave as status message for now.
}

