import NetInfo from '@react-native-community/netinfo';
import { useEffect, useState } from 'react';
import { View, Text } from 'react-native';
import { colors, fonts, spacing } from '../theme/tokens';

export function OfflineBanner() {
  const [offline, setOffline] = useState(false);
  useEffect(() => {
    const unsub = NetInfo.addEventListener(s => setOffline(!(s.isConnected ?? true)));
    return unsub;
  }, []);
  if (!offline) return null;
  return (
    <View style={{ backgroundColor: colors.text, paddingVertical: spacing.sm, paddingHorizontal: spacing.md }}>
      <Text style={{ fontFamily: fonts.bodySemiBold, fontSize: 13, color: colors.background, textAlign: 'center' }}>
        No internet connection
      </Text>
    </View>
  );
}

In app/_layout.tsx, render <OfflineBanner /> at the very top of the root layout,
above the <Stack>. Wrap both in a <View style={{ flex:1 }}>.
```

